"use client";

export {
  AomiParaPluginProvider,
  type AomiParaPluginProviderProps,
} from "./ParaPluginProvider";
export { paraPlugin, registerAomiParaWalletProvider } from "./para-plugin";

"use client";

import { registerWalletBrand } from "../../catalog/wallet-branding";

/**
 * Canonical brand key for Para-backed wallets. Registering it here keeps the
 * shared brand resolver (`runtime/evm/brands`) free of any hardcoded provider
 * name — generic code resolves "para" only because this module ran. Importing
 * `PARA_BRAND_KEY` from a used call site guarantees the registration executes.
 */
export const PARA_BRAND_KEY = "para";

registerWalletBrand({ key: PARA_BRAND_KEY, matchers: ["para"] });

"use client";

import { useMemo, type ReactNode } from "react";
import {
  Environment,
  ParaProvider,
  type TOAuthMethod,
} from "@getpara/react-sdk";
import "@getpara/react-sdk/styles.css";
import type {
  AuthConfig,
  AuthMethodId,
  ProvidersConfig,
  WalletsConfig,
} from "../../config/types";
import {
  registerWalletProvider,
  type WalletProviderPlugin,
} from "../plugin-registry";
import { AomiParaPluginProvider } from "./ParaPluginProvider";
import { defaultOAuthMethods } from "./para-auth";

type ParaSvmOptions = {
  enabled?: boolean;
  networks?: Exclude<WalletsConfig["solana"], false | undefined>["networks"];
  preferDirectSend?: boolean;
};

function toParaEnvironment(value?: "PROD" | "BETA") {
  if (!value) return Environment.BETA;
  return value === "PROD" ? Environment.PROD : Environment.BETA;
}

function toParaOAuthMethods(
  methods: readonly AuthMethodId[] | undefined,
): TOAuthMethod[] {
  if (!methods) return defaultOAuthMethods;
  const map = {
    google: "GOOGLE",
    apple: "APPLE",
    discord: "DISCORD",
    x: "TWITTER",
    farcaster: "FARCASTER",
    telegram: "TELEGRAM",
  } as const satisfies Partial<Record<AuthMethodId, TOAuthMethod>>;
  const resolved = methods
    .map((method) => map[method as keyof typeof map])
    .filter((method): method is NonNullable<typeof method> => Boolean(method));
  return resolved.length ? resolved : defaultOAuthMethods;
}

function toProviderSvmOptions(
  solana: WalletsConfig["solana"],
): ParaSvmOptions | undefined {
  if (solana === false) return { enabled: false };
  if (!solana) return undefined;
  return {
    networks: solana.networks,
    preferDirectSend: solana.preferDirectSend,
  };
}

function isParaAuth(auth: AuthConfig | undefined): boolean {
  return auth !== false && auth?.provider === "para";
}

function ParaAuthLayer({
  auth,
  children,
  providers,
}: {
  auth?: AuthConfig;
  children: ReactNode;
  providers?: ProvidersConfig;
}) {
  const enabled = isParaAuth(auth);
  const para = providers?.para === false ? undefined : providers?.para;
  const apiKey = para?.apiKey ?? process.env.NEXT_PUBLIC_PARA_API_KEY;
  const paraClientConfig = useMemo(
    () =>
      apiKey
        ? {
            apiKey,
            env: toParaEnvironment(para?.environment),
          }
        : null,
    [apiKey, para?.environment],
  );
  const paraConfig = useMemo(
    () => ({ appName: para?.appName ?? "Aomi" }),
    [para?.appName],
  );
  const paraModalConfig = useMemo(
    () => ({
      disableEmailLogin: false,
      oAuthMethods: toParaOAuthMethods(
        enabled && auth !== false && auth?.provider === "para"
          ? auth.methods
          : undefined,
      ),
    }),
    [auth, enabled],
  );
  const externalWalletConfig = useMemo(
    () => ({
      appDescription: para?.appDescription ?? "Aomi widget",
      appUrl:
        para?.appUrl ??
        (typeof window !== "undefined"
          ? window.location.origin
          : "https://aomi.dev"),
      wallets: [],
      walletConnect: undefined,
    }),
    [para?.appDescription, para?.appUrl],
  );

  if (!enabled || !paraClientConfig) {
    return <>{children}</>;
  }

  return (
    <ParaProvider
      paraClientConfig={paraClientConfig}
      config={paraConfig}
      paraModalConfig={paraModalConfig}
      externalWalletConfig={externalWalletConfig}
    >
      {children}
    </ParaProvider>
  );
}

export const paraPlugin: WalletProviderPlugin = {
  id: "para",
  authMode: "additive",
  isAvailable: ({ auth, providers }) => {
    const enabled = isParaAuth(auth);
    const para = providers?.para === false ? undefined : providers?.para;
    return Boolean(
      enabled && (para?.apiKey ?? process.env.NEXT_PUBLIC_PARA_API_KEY),
    );
  },
  wrap: (props) => <ParaAuthLayer {...props} />,
  renderComposer: ({
    auth,
    children,
    execution,
    selectedSolanaNetwork,
    setSelectedSolanaNetworkId,
    solanaRuntimeConfig,
    supportedChains,
    supportedSolanaNetworks,
  }) => (
    <AomiParaPluginProvider
      execution={execution}
      oAuthMethods={toParaOAuthMethods(
        auth !== false && auth?.provider === "para" ? auth.methods : undefined,
      )}
      selectedSolanaNetwork={selectedSolanaNetwork}
      setSelectedSolanaNetworkId={setSelectedSolanaNetworkId}
      supportedChains={supportedChains}
      supportedSolanaNetworks={supportedSolanaNetworks}
      svmConfig={solanaRuntimeConfig}
    >
      {children}
    </AomiParaPluginProvider>
  ),
  detectSugar: (input) => {
    if (
      input.auth !== false &&
      input.auth?.provider === "para" &&
      "apiKey" in input.auth
    ) {
      return {
        children: input.children,
        providers: {
          para: {
            apiKey: input.auth.apiKey,
            environment: input.auth.environment,
            appName: input.auth.appName,
            appDescription: input.auth.appDescription,
          },
        },
        auth: { provider: "para", methods: input.auth.methods },
      };
    }
    return null;
  },
};

export function registerAomiParaWalletProvider(): void {
  registerWalletProvider(paraPlugin);
}

registerAomiParaWalletProvider();

"use client";

import { useCallback, useMemo, type ReactNode } from "react";
import type { Chain } from "viem";
import type { TOAuthMethod } from "@getpara/react-sdk";
import { AomiWalletKitComposer } from "../../composer/AomiWalletKitComposer";
import type {
  AuthRuntime,
  ExecutionRuntime,
  SvmWalletRuntime,
} from "../../composer/types";
import type { ExecutionConfig } from "../../config/types";
import { useAomiWalletNetworkPreferences } from "../../network-preferences";
import {
  useEvmWalletRuntime,
  type EvmWalletRuntimeProviderHooks,
} from "../../runtime/evm/wallet-runtime";
import { toSocialLoginOption } from "../../runtime/evm/brands";
import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { DEFAULT_SVM_CLUSTER } from "../../catalog/svm-networks";
import { REGISTRY_STORAGE_KEY } from "../../registry/types";
import { walletDebug } from "../../wallet-debug";
import { buildEvmExecutionRuntime } from "../../execution/execution-runtime";
import type { AomiAccount, SvmNetworkOption } from "../../types";
import {
  resolveAAProviderState,
  resolveAASponsorship,
} from "../../execution/aa-provider-state";
import { PARA_BRAND_KEY } from "./para-brand";
import {
  DEFAULT_SVM_ENDPOINT,
  useSafeSvmWallet,
  useSvmWalletRuntime,
} from "../../runtime/svm/wallet-runtime";
import { useParaSessionSource } from "./sources/para-session-source";
import { isParaEmbeddedAccount } from "./para-embedded-wallet";
import {
  defaultOAuthMethods,
  inferParaAuthMethod,
  resolveParaAuthValue,
  useSafeIssueJwt,
  useSafeLogout,
  useSafeParaAccount,
  useSafeParaClient,
  useSafeParaModal,
} from "./para-auth";

type PluginSvmRuntimeConfig = Pick<
  {
    cluster: SvmNetworkOption["cluster"];
    rpcHttpUrl: string;
    rpcWsUrl?: string;
    preferDirectSend: boolean;
  },
  "cluster" | "rpcHttpUrl" | "rpcWsUrl" | "preferDirectSend"
>;

export type AomiParaPluginProviderProps = {
  children: ReactNode;
  supportedChains?: readonly Chain[];
  svmConfig?: PluginSvmRuntimeConfig;
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedSolanaNetworkId?: (networkId: string) => void;
  supportedSolanaNetworks?: readonly SvmNetworkOption[];
  oAuthMethods?: readonly TOAuthMethod[];
  execution?: ExecutionConfig;
};

export function AomiParaPluginProvider({
  children,
  supportedChains: configuredChains,
  svmConfig,
  selectedSolanaNetwork: selectedSolanaNetworkProp,
  setSelectedSolanaNetworkId: setSelectedSolanaNetworkIdProp,
  supportedSolanaNetworks: supportedSolanaNetworksProp,
  oAuthMethods = defaultOAuthMethods,
  execution,
}: AomiParaPluginProviderProps) {
  const paraAccount = useSafeParaAccount();
  const paraSession = useSafeParaClient();
  const issueJwt = useSafeIssueJwt();
  const paraLogout = useSafeLogout();
  const paraModal = useSafeParaModal();
  const svmWallet = useSafeSvmWallet();
  const logoutParaSession = useCallback(async () => {
    if (paraLogout) {
      try {
        walletDebug("para:logout", { via: "useLogout" });
        await paraLogout();
        walletDebug("para:logout", { result: "ok" });
        return;
      } catch (error) {
        walletDebug("para:logout", { failed: String(error) });
        console.warn("[aomi-wallet-kit] Para logout failed", error);
      }
    }

    const clientLogout = (
      paraSession as unknown as {
        logout?: (args?: unknown) => Promise<unknown>;
      } | null
    )?.logout;
    if (typeof clientLogout !== "function") {
      walletDebug("para:logout", {
        skip: paraLogout ? "hook-failed-no-client-fallback" : "no-path",
      });
      return;
    }
    try {
      walletDebug("para:logout", { via: "client" });
      await clientLogout.call(paraSession);
      walletDebug("para:logout", { result: "ok" });
    } catch (error) {
      walletDebug("para:logout", { failed: String(error) });
      console.warn("[aomi-wallet-kit] Para logout failed", error);
    }
  }, [paraLogout, paraSession]);
  const {
    selectedEvmChainId,
    selectedSolanaNetwork: preferenceSelectedSolanaNetwork,
    setSelectedEvmChainId,
    setSelectedSolanaNetworkId: preferenceSetSelectedSolanaNetworkId,
    supportedSolanaNetworks: preferenceSupportedSolanaNetworks,
  } = useAomiWalletNetworkPreferences();
  const selectedSolanaNetwork =
    selectedSolanaNetworkProp ?? preferenceSelectedSolanaNetwork;
  const setSelectedSolanaNetworkId =
    setSelectedSolanaNetworkIdProp ?? preferenceSetSelectedSolanaNetworkId;
  const supportedSolanaNetworks =
    supportedSolanaNetworksProp ?? preferenceSupportedSolanaNetworks;
  const resolvedAdapterSvmConfig = useMemo<PluginSvmRuntimeConfig>(
    () => ({
      cluster: svmConfig?.cluster ?? DEFAULT_SVM_CLUSTER,
      rpcHttpUrl:
        svmConfig?.rpcHttpUrl ??
        process.env.NEXT_PUBLIC_SOLANA_RPC_URL ??
        DEFAULT_SVM_ENDPOINT,
      rpcWsUrl:
        svmConfig?.rpcWsUrl ??
        process.env.NEXT_PUBLIC_SOLANA_RPC_WS_URL ??
        undefined,
      preferDirectSend: svmConfig?.preferDirectSend ?? true,
    }),
    [svmConfig],
  );
  const providerHooks = useMemo<EvmWalletRuntimeProviderHooks>(
    () => ({
      providerLogout: logoutParaSession,
      isProviderInternalConnector: (connector) =>
        connector.id === PARA_BRAND_KEY ||
        canonicalWalletKey(connector.name ?? "") === PARA_BRAND_KEY,
      onProviderReconnectRequested: (store) => {
        store.dispatch({
          type: "user/provider-reconnect-requested",
          now: Date.now(),
        });
      },
      onConnectFallback: (store) => {
        store.dispatch({
          type: "provider/auth-flow-started",
          reason: "provider-auth-connect-fallback",
          now: Date.now(),
        });
        paraModal?.openModal({ step: "AUTH_MAIN" });
      },
      onAccountDisconnectPlanned: (disconnectPlan) => {
        if (
          disconnectPlan.isProviderOwnedAccount &&
          disconnectPlan.otherConnectionsRemain
        ) {
          walletDebug("para:detach", {
            address: disconnectPlan.targetAddress,
            reason: "preserve-external-wallets",
          });
        }
      },
    }),
    [logoutParaSession, paraModal],
  );
  const evmRuntime = useEvmWalletRuntime({
    configuredChains,
    selectedEvmChainId,
    setSelectedEvmChainId,
    storageKey: REGISTRY_STORAGE_KEY,
    providerHooks,
  });
  const { registryStore, registryState } = evmRuntime;
  useParaSessionSource(registryStore, { paraAccount });
  const startParaAuthFlow = useCallback(
    (reason: string) => {
      registryStore.dispatch({
        type: "provider/auth-flow-started",
        reason,
        now: Date.now(),
      });
    },
    [registryStore],
  );
  const registryDetachedParaAddresses = registryState.intents
    .providerSessionDetached
    ? registryState.intents.droppedAddresses
    : [];
  const paraSessionConnected = Boolean(
    paraAccount.isConnected || paraAccount.embedded.isConnected,
  );
  const paraSessionLocallyDetached = Boolean(
    paraSessionConnected && registryState.intents.providerSessionDetached,
  );
  const exposeParaSession = Boolean(
    paraSessionConnected && !paraSessionLocallyDetached,
  );
  const paraAuthMethod = inferParaAuthMethod(paraAccount.embedded);
  const paraAuthValue = resolveParaAuthValue(
    paraAccount.embedded,
    paraAuthMethod,
  );
  const embeddedPrimary = exposeParaSession
    ? (paraAuthValue ??
      paraAccount.embedded.identifier ??
      paraAccount.embedded.userId ??
      undefined)
    : undefined;
  const authRuntime = useMemo<AuthRuntime>(
    () => ({
      provider: "para",
      sessionProvider: "para",
      embeddedProvider: "para",
      legacyWalletProvider: "para",
      providerLabel: "Para",
      status: paraAccount.isLoading
        ? "booting"
        : exposeParaSession
          ? "authenticated"
          : "unauthenticated",
      subject: exposeParaSession ? paraAccount.embedded.userId : undefined,
      primaryLabel: embeddedPrimary,
      authMethod: embeddedPrimary ? paraAuthMethod : undefined,
      authValue: embeddedPrimary ? paraAuthValue : undefined,
      methods: paraModal
        ? Array.from(oAuthMethods).map(toSocialLoginOption)
        : [],
      canOpenModal: Boolean(paraModal),
      startFlow: startParaAuthFlow,
      login: async (reason: string, step = "AUTH_MAIN") => {
        registryStore.dispatch({
          type: "user/provider-reconnect-requested",
          now: Date.now(),
        });
        startParaAuthFlow(reason);
        paraModal?.openModal({ step });
      },
      openAccountUI: async (reason: string, step = "ACCOUNT_MAIN") => {
        startParaAuthFlow(reason);
        paraModal?.openModal({ step });
      },
      logout: logoutParaSession,
      getCredential: exposeParaSession ? (issueJwt ?? undefined) : undefined,
    }),
    [
      embeddedPrimary,
      exposeParaSession,
      issueJwt,
      logoutParaSession,
      oAuthMethods,
      paraAccount.embedded.userId,
      paraAccount.embedded,
      paraAccount.isLoading,
      paraAuthValue,
      paraAuthMethod,
      paraModal,
      registryStore,
      startParaAuthFlow,
    ],
  );
  const svmRuntime = useSvmWalletRuntime({
    registryStore,
    selectedNetwork: selectedSolanaNetwork,
    supportedNetworks: supportedSolanaNetworks,
    setSelectedNetworkId: setSelectedSolanaNetworkId,
    wallet: svmWallet,
  });
  const providerEvmWalletOptions = useMemo(() => [], []);
  const transformEvmIdentity = useCallback(
    (identity: ReturnType<typeof evmRuntime.identity>) => {
      if (
        paraSessionLocallyDetached &&
        identity.address &&
        registryDetachedParaAddresses.includes(identity.address.toLowerCase())
      ) {
        return {};
      }
      return identity;
    },
    [paraSessionLocallyDetached, registryDetachedParaAddresses],
  );
  const transformAccounts = useCallback(
    (accounts: AomiAccount[]) =>
      accounts
        .filter((account) => {
          if (!paraSessionLocallyDetached) return true;
          if (account.family !== "evm") return true;
          const address = account.address.toLowerCase();
          if (registryDetachedParaAddresses.includes(address)) return false;
          return !isParaEmbeddedAccount(account);
        })
        .map((account) => {
          if (!exposeParaSession || !isParaEmbeddedAccount(account)) {
            return account;
          }
          return {
            ...account,
            manageable: Boolean(paraModal),
            actions: [
              ...(paraModal
                ? [{ kind: "manage" as const, label: "Manage" }]
                : []),
              { kind: "signout" as const, label: "Sign out" },
            ],
          };
        }),
    [
      exposeParaSession,
      paraModal,
      paraSessionLocallyDetached,
      registryDetachedParaAddresses,
    ],
  );
  const canManageParaAccount = useCallback(
    (account: AomiAccount) =>
      Boolean(paraModal) && exposeParaSession && isParaEmbeddedAccount(account),
    [exposeParaSession, paraModal],
  );
  const sponsorship = useMemo(
    () => resolveAASponsorship(execution?.provider ?? "auto"),
    [execution?.provider],
  );
  const executionRuntime = useMemo<ExecutionRuntime>(
    () => ({
      sponsorship,
      evm: buildEvmExecutionRuntime(evmRuntime, {
        aaModes: execution?.modes,
        aaOwner: execution?.owner ?? "auto",
        aaPolicy: execution?.aa ?? "optional",
        aaProvider: execution?.provider ?? "auto",
        resolveAAProviderState: async (params, context) =>
          resolveAAProviderState({
            ...params,
            ownerStrategy: {
              kind: "provider-session",
              provider: "para",
              session: paraSession,
            },
            walletClient: context.walletClient,
            address: context.address,
          }),
      }),
    }),
    [evmRuntime, execution, paraSession, sponsorship],
  );

  return (
    <AomiWalletKitComposer
      auth={authRuntime}
      evm={evmRuntime}
      svm={svmRuntime}
      execution={executionRuntime}
      additionalEvmWalletOptions={providerEvmWalletOptions}
      transformEvmIdentity={transformEvmIdentity}
      transformAccounts={transformAccounts}
      canManageAccount={canManageParaAccount}
      supportedChains={evmRuntime.supportedChains}
    >
      {children}
    </AomiWalletKitComposer>
  );
}

"use client";

import {
  useAccount as useParaAccount,
  useClient as useParaClient,
  useIssueJwt,
  useLogout,
  useModal,
  type TOAuthMethod,
} from "@getpara/react-sdk";
import type ParaWeb from "@getpara/react-sdk";
import type { AomiAccountCredential, AomiLoginMethod } from "../../types";
import { inferAuthMethod } from "../../identity";

export type ParaAccountShape = {
  isLoading: boolean;
  isConnected: boolean;
  connectionType?: "embedded" | "external" | "both" | "none";
  embedded: {
    isConnected?: boolean;
    isGuestMode?: boolean;
    userId?: string;
    auth?: {
      email?: string;
      phone?: string;
      farcasterUsername?: string;
      telegramUserId?: string;
      externalWalletAddress?: string;
    };
    authType?: string;
    identifier?: string;
    email?: string;
    phone?: string;
    farcasterUsername?: string;
    telegramUserId?: string;
    externalWalletAddress?: string;
    authMethods?: Set<unknown>;
    wallets?: Array<{ address?: string; type?: string; isExternal?: boolean }>;
  };
  external: {
    evm?: {
      address?: string;
      chainId?: number | string;
    };
  };
};

export const DISCONNECTED_PARA_ACCOUNT: ParaAccountShape = {
  isLoading: false,
  isConnected: false,
  embedded: {},
  external: {},
};

export const defaultOAuthMethods: TOAuthMethod[] = ["GOOGLE"];

export function useSafeParaAccount(): ParaAccountShape {
  try {
    return useParaAccount() as ParaAccountShape;
  } catch {
    return DISCONNECTED_PARA_ACCOUNT;
  }
}

export function useSafeParaModal(): {
  openModal: (args?: { step?: string }) => void;
} | null {
  try {
    return useModal() as { openModal: (args?: { step?: string }) => void };
  } catch {
    return null;
  }
}

export function useSafeParaClient(): ParaWeb | null {
  try {
    return useParaClient() ?? null;
  } catch {
    return null;
  }
}

export function useSafeIssueJwt():
  | (() => Promise<AomiAccountCredential | null>)
  | null {
  try {
    const { issueJwtAsync } = useIssueJwt();
    return async () => {
      const result = await issueJwtAsync();
      const token = result?.token?.trim();
      return token
        ? {
            provider: "para",
            providerToken: token,
          }
        : null;
    };
  } catch {
    return null;
  }
}

export function useSafeLogout(): (() => Promise<void>) | null {
  try {
    const { logoutAsync } = useLogout();
    return async () => {
      await logoutAsync();
    };
  } catch {
    return null;
  }
}

export function resolveParaAuthValue(
  embedded: ParaAccountShape["embedded"],
  authMethod: AomiLoginMethod | undefined,
): string | undefined {
  if (authMethod === "telegram") {
    return embedded.telegramUserId ?? embedded.auth?.telegramUserId;
  }
  if (authMethod === "farcaster") {
    return embedded.farcasterUsername ?? embedded.auth?.farcasterUsername;
  }
  if (authMethod === "phone") {
    return embedded.phone ?? embedded.auth?.phone;
  }
  if (authMethod === "wagmi") {
    return (
      embedded.externalWalletAddress ?? embedded.auth?.externalWalletAddress
    );
  }
  if (!authMethod) {
    return undefined;
  }
  return embedded.email ?? embedded.auth?.email ?? embedded.identifier;
}

export function inferParaAuthMethod(
  embedded: ParaAccountShape["embedded"],
): AomiLoginMethod | undefined {
  const fromAuthMethods = inferAuthMethod(embedded.authMethods);
  if (fromAuthMethods) return fromAuthMethods;

  const normalizedAuthType = embedded.authType?.toLowerCase();
  if (!normalizedAuthType) return undefined;
  if (normalizedAuthType === "externalwallet") return "wagmi";
  if (normalizedAuthType === "email") return "email";
  if (normalizedAuthType === "phone") return "phone";
  if (normalizedAuthType === "farcaster") return "farcaster";
  if (normalizedAuthType === "telegram") return "telegram";
  return undefined;
}

"use client";

import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { PARA_BRAND_KEY } from "./para-brand";
import type { AomiAccount } from "../../types";

export function isParaEmbeddedAccount(account: AomiAccount): boolean {
  return (
    canonicalWalletKey(
      `${account.id} ${account.walletName ?? ""} ${
        account.connectorIds?.join(" ") ?? ""
      }`,
    ) === PARA_BRAND_KEY
  );
}

"use client";

import { useEffect, useMemo, useRef, useSyncExternalStore } from "react";
import { WalletRegistryStore, type CommandExecutors } from "./store";
import type { WalletRegistryState } from "./types";

export function useWalletRegistry(opts: {
  executors: CommandExecutors;
  storageKey: string;
}): {
  store: WalletRegistryStore;
  state: WalletRegistryState;
} {
  const executorsRef = useRef(opts.executors);
  useEffect(() => {
    executorsRef.current = opts.executors;
  }, [opts.executors]);

  const store = useMemo(
    () =>
      new WalletRegistryStore({
        executors: {
          wagmiReconnect: (stableIds) =>
            executorsRef.current.wagmiReconnect(stableIds),
          wagmiConnect: (stableId) =>
            executorsRef.current.wagmiConnect(stableId),
          wagmiDisconnect: (uid) => executorsRef.current.wagmiDisconnect(uid),
          providerLogout: () => executorsRef.current.providerLogout(),
        },
        storageKey: opts.storageKey,
        initialNow: Date.now(),
      }),
    [opts.storageKey],
  );
  useEffect(() => () => store.dispose(), [store]);
  const state = useSyncExternalStore(
    (callback) => store.subscribe(callback),
    () => store.getSnapshot(),
    () => store.getSnapshot(),
  );

  return { store, state };
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import {
  useSafeConnectors,
  useSafeRawWagmiConnections,
  useSafeWagmiConfig,
} from "./safe-hooks";
import type { WalletRegistryStore } from "../../registry/store";
import { useEvmProviderBrands } from "./brands";

export function useWagmiRegistrySource(store: WalletRegistryStore): void {
  const connections = useSafeRawWagmiConnections();
  const connectors = useSafeConnectors();
  const wagmiConfig = useSafeWagmiConfig();
  const brandInputs = useMemo(
    () =>
      connections.flatMap((connection) =>
        connection.accounts.map((address) => ({
          connectorId: connection.connectorUid,
          address,
        })),
      ),
    [connections],
  );
  const brands = useEvmProviderBrands(brandInputs, connectors);
  const connectorKey = useMemo(
    () =>
      connectors
        .map((connector) => `${connector.uid}:${connector.id}`)
        .sort()
        .join("|"),
    [connectors],
  );
  const chainKey = useMemo(
    () => wagmiConfig.chains.map((chain) => chain.id).join("|"),
    [wagmiConfig.chains],
  );
  const previousConfigKeyRef = useRef<string | null>(null);
  const previousConnectionsKeyRef = useRef<string | null>(null);
  const previousBrandsKeyRef = useRef<string | null>(null);

  useEffect(() => {
    const mapped = connections.flatMap((connection) =>
      connection.accounts.map((address) => ({
        family: "evm" as const,
        uid: connection.connectorUid,
        stableId: connection.connectorId,
        address,
        addresses: [...connection.accounts],
        chainId: connection.chainId,
        walletName: brands[connection.connectorUid] ?? connection.connectorName,
      })),
    );
    const key = JSON.stringify(
      mapped
        .map((connection) => ({
          uid: connection.uid,
          stableId: connection.stableId,
          address: connection.address.toLowerCase(),
          addresses: connection.addresses.map((address) =>
            address.toLowerCase(),
          ),
          chainId: connection.chainId ?? null,
          walletName: connection.walletName ?? null,
        }))
        .sort((left, right) =>
          `${left.uid}:${left.address}`.localeCompare(
            `${right.uid}:${right.address}`,
          ),
        ),
    );
    if (previousConnectionsKeyRef.current === key) return;
    previousConnectionsKeyRef.current = key;
    store.dispatch({
      type: "wagmi/connections-changed",
      connections: mapped,
      now: Date.now(),
    });
  }, [brands, connections, store]);

  useEffect(() => {
    const key = `${connectorKey}::${chainKey}`;
    if (previousConfigKeyRef.current === null) {
      previousConfigKeyRef.current = key;
      return;
    }
    if (previousConfigKeyRef.current === key) return;
    previousConfigKeyRef.current = key;
    store.dispatch({ type: "wagmi/config-rebuilt", now: Date.now() });
  }, [chainKey, connectorKey, store]);

  useEffect(() => {
    const key = JSON.stringify(
      Object.entries(brands).sort(([left], [right]) =>
        left.localeCompare(right),
      ),
    );
    if (previousBrandsKeyRef.current === key) return;
    previousBrandsKeyRef.current = key;
    store.dispatch({ type: "wagmi/brands-changed", brands });
  }, [brands, store]);
}

