"use client";

import { useCallback, useEffect, useMemo, useRef } from "react";
import type { Chain } from "viem";
import type { Connector } from "wagmi";
import type { AomiAccount, AomiWalletOption } from "../../types";
import { selectAccounts, selectEvmIdentity } from "../../registry/selectors";
import type { WalletRegistryStore } from "../../registry/store";
import { useWalletRegistry } from "../../registry/use-wallet-registry";
import type { WalletRegistryState } from "../../registry/types";
import type { WalletRuntime } from "../../composer/types";
import {
  dedupeWalletOptions,
  detectEvmProviderBrand,
  toEvmWalletOption,
  useInstalledWalletFlags,
  walletOptionIsDetected,
} from "./brands";
import { canonicalWalletKey } from "../../catalog/wallet-branding";
import { planEvmAccountDisconnect } from "./disconnect-plan";
import { useWagmiRegistrySource } from "./registry-source";
import {
  useSafeCapabilities,
  useSafeConnect,
  useSafeConnections,
  useSafeConnectors,
  useSafeDisconnect,
  useSafeGetWalletClientFor,
  useSafeReconnect,
  useSafeSendCallsSync,
  useSafeSendTransaction,
  useSafeSignMessage,
  useSafeSignTypedData,
  useSafeSwitchAccount,
  useSafeSwitchChain,
  useSafeWagmiConfig,
  useSafeWalletClient,
} from "./safe-hooks";
import { walletDebug } from "../../wallet-debug";

export type EvmWalletRuntimeProviderHooks = {
  /**
   * Provider-owned account/session logout. The registry command is still named
   * `provider/logout` for compatibility, but the runtime only sees a generic
   * callback here.
   */
  providerLogout?: () => Promise<void>;
  /**
   * Called before connecting a provider-owned embedded wallet option. Hosted
   * providers use this to re-attach a session without making generic wagmi code
   * know about a specific SDK.
   */
  onProviderReconnectRequested?: (store: WalletRegistryStore) => void;
  /**
   * Called when a requested EVM wallet option cannot be matched to a concrete
   * wagmi connector. Hosted providers use this to open their auth modal.
   */
  onConnectFallback?: (store: WalletRegistryStore) => void;
  /**
   * Keep provider-owned connector rows out of normal external wallet lists.
   */
  isProviderInternalConnector?: (connector: Connector) => boolean;
  /**
   * Extra side effect after an EVM account disconnect plan runs. Hosted
   * providers use this only for debug/analytics around detached embedded
   * accounts.
   */
  onAccountDisconnectPlanned?: (
    plan: ReturnType<typeof planEvmAccountDisconnect>,
  ) => void;
};

export type EvmWalletRuntime = WalletRuntime<"evm"> & {
  registryStore: WalletRegistryStore;
  registryState: WalletRegistryState;
  activeEvmConnection?: WalletRegistryState["connections"][number];
  activeConnector?: Connector;
  capabilities?: ReturnType<typeof useSafeCapabilities>["capabilities"];
  chainsById: Record<number, Chain>;
  supportedChains: readonly Chain[];
  walletClient: ReturnType<typeof useSafeWalletClient>["walletClient"];
  getWalletClientFor: ReturnType<typeof useSafeGetWalletClientFor>;
  sendTransactionAsync: ReturnType<
    typeof useSafeSendTransaction
  >["sendTransactionAsync"];
  sendCallsSyncAsync: ReturnType<
    typeof useSafeSendCallsSync
  >["sendCallsSyncAsync"];
  signTypedDataAsync: ReturnType<
    typeof useSafeSignTypedData
  >["signTypedDataAsync"];
  signMessageAsync: ReturnType<typeof useSafeSignMessage>["signMessageAsync"];
  switchChainAsync: ReturnType<typeof useSafeSwitchChain>["switchChainAsync"];
  isSwitchingChain: boolean;
  shouldUseExternalSigner: boolean;
};

async function findConnectorByProviderBrand(
  connectors: readonly Connector[],
  expectedKey: string,
  excludeUid?: string,
): Promise<Connector | undefined> {
  for (const connector of connectors) {
    if (connector.uid === excludeUid || !connector.getProvider) continue;
    try {
      const provider = await connector.getProvider();
      const brand = detectEvmProviderBrand(provider);
      if (brand && canonicalWalletKey(brand) === expectedKey) {
        return connector;
      }
    } catch {
      // Provider sniffing is best-effort; keep trying other connectors.
    }
  }
  return undefined;
}

function findActiveEvmConnection(
  state: WalletRegistryState,
): WalletRegistryState["connections"][number] | undefined {
  const active = state.activeByFamily.evm;
  if (!active) return undefined;
  return state.connections.find((connection) => {
    if (connection.family !== "evm") return false;
    if (active.uid && connection.uid === active.uid) return true;
    if (active.stableId && connection.stableId !== active.stableId) {
      return false;
    }
    return connection.address.toLowerCase() === active.address.toLowerCase();
  });
}

export function useEvmWalletRuntime({
  configuredChains,
  selectedEvmChainId,
  setSelectedEvmChainId,
  storageKey,
  providerHooks = {},
}: {
  configuredChains?: readonly Chain[];
  selectedEvmChainId?: number;
  setSelectedEvmChainId: (chainId: number | undefined) => void;
  storageKey: string;
  providerHooks?: EvmWalletRuntimeProviderHooks;
}): EvmWalletRuntime {
  const { walletClient } = useSafeWalletClient();
  const { switchChainAsync, isPending } = useSafeSwitchChain();
  const { disconnectAsync: wagmiDisconnectAsync } = useSafeDisconnect();
  const { reconnectAsync: wagmiReconnectAsync } = useSafeReconnect();
  const installedWalletFlags = useInstalledWalletFlags();
  const evmConnections = useSafeConnections();
  const evmConnectors = useSafeConnectors();
  const { connectAsync: wagmiConnectAsync } = useSafeConnect();
  const { switchAccountAsync } = useSafeSwitchAccount();
  const { sendTransactionAsync } = useSafeSendTransaction();
  const { sendCallsSyncAsync } = useSafeSendCallsSync();
  const { signTypedDataAsync } = useSafeSignTypedData();
  const { signMessageAsync } = useSafeSignMessage();
  const getWalletClientFor = useSafeGetWalletClientFor();
  const wagmiConfig = useSafeWagmiConfig();

  const registryExecutors = useMemo(
    () => ({
      async wagmiReconnect(stableIds: string[]) {
        if (!wagmiReconnectAsync) return;
        const targets: Connector[] = stableIds
          .map((stableId) =>
            evmConnectors.find((candidate) => candidate.id === stableId),
          )
          .filter((connector): connector is Connector => Boolean(connector));
        if (targets.length === 0) {
          walletDebug("registry:command-skip", {
            kind: "wagmi/reconnect",
            stableIds,
            reason: "connector-missing",
          });
          return;
        }
        const result = await wagmiReconnectAsync({
          connectors: targets,
        } as never);
        if (Array.isArray(result) && result.length === 0) {
          walletDebug("evm:heal", {
            action: "reconnect-empty",
            stableIds,
          });
        }
      },
      async wagmiConnect(stableId: string) {
        if (!wagmiConnectAsync) return;
        const target = evmConnectors.find(
          (candidate) => candidate.id === stableId,
        );
        if (!target) {
          walletDebug("registry:command-skip", {
            kind: "wagmi/connect",
            stableId,
            reason: "connector-missing",
          });
          return;
        }
        await wagmiConnectAsync({ connector: target });
      },
      async wagmiDisconnect(uid: string) {
        if (!wagmiDisconnectAsync) return;
        const target = wagmiConfig.connectors.find(
          (candidate) => candidate.uid === uid,
        );
        if (!target) {
          walletDebug("registry:command-skip", {
            kind: "wagmi/disconnect",
            uid,
            reason: "connector-missing",
          });
          return;
        }
        await wagmiDisconnectAsync({ connector: target });
      },
      providerLogout: providerHooks.providerLogout ?? (async () => undefined),
    }),
    [
      evmConnectors,
      providerHooks.providerLogout,
      wagmiConfig.connectors,
      wagmiConnectAsync,
      wagmiDisconnectAsync,
      wagmiReconnectAsync,
    ],
  );
  const { store: registryStore, state: registryState } = useWalletRegistry({
    executors: registryExecutors,
    storageKey,
  });
  useWagmiRegistrySource(registryStore);

  const supportedChains = useMemo(
    () => configuredChains ?? wagmiConfig.chains,
    [configuredChains, wagmiConfig.chains],
  );
  const chainsById = useMemo<Record<number, Chain>>(
    () => Object.fromEntries(supportedChains.map((chain) => [chain.id, chain])),
    [supportedChains],
  );
  const activeEvmConnection = useMemo(
    () => findActiveEvmConnection(registryState),
    [registryState],
  );
  const activeConnector = useMemo(() => {
    const active = registryState.activeByFamily.evm;
    if (!active?.uid) return undefined;
    return wagmiConfig.connectors.find(
      (candidate) => candidate.uid === active.uid,
    );
  }, [registryState.activeByFamily.evm, wagmiConfig.connectors]);
  const { capabilities } = useSafeCapabilities({
    account: activeEvmConnection?.address as `0x${string}` | undefined,
    connector: activeConnector,
    stableId: activeEvmConnection?.stableId,
    walletName: activeEvmConnection?.walletName,
  });
  const evmSwitchInFlightRef = useRef(false);

  useEffect(() => {
    const chainId = activeEvmConnection?.chainId;
    if (
      evmSwitchInFlightRef.current ||
      !chainId ||
      !chainsById[chainId] ||
      chainId === selectedEvmChainId
    ) {
      return;
    }
    walletDebug("evm:chain-external-sync", {
      chainId,
      previous: selectedEvmChainId ?? null,
    });
    setSelectedEvmChainId(chainId);
  }, [
    activeEvmConnection?.chainId,
    chainsById,
    selectedEvmChainId,
    setSelectedEvmChainId,
  ]);

  useEffect(() => {
    walletDebug("evm:connections-changed", {
      connections: evmConnections.map((conn) => ({
        connector: conn.connectorName,
        uid: conn.connectorId,
        address: conn.address,
      })),
    });
  }, [evmConnections]);

  const evmWalletOptions = useMemo(
    () =>
      dedupeWalletOptions(
        evmConnectors
          .map((connector) =>
            toEvmWalletOption(connector, installedWalletFlags),
          )
          .filter((option) => {
            const connector = evmConnectors.find(
              (candidate) => candidate.uid === option.id,
            );
            if (
              connector &&
              providerHooks.isProviderInternalConnector?.(connector)
            ) {
              return false;
            }
            return walletOptionIsDetected(option);
          }),
      ),
    [evmConnectors, installedWalletFlags, providerHooks],
  );

  const selectAccount = useCallback(
    async (id: string) => {
      const connection = registryStore
        .getSnapshot()
        .connections.find((conn) => conn.family === "evm" && conn.uid === id);
      if (!connection) return;
      registryStore.dispatch({
        type: "user/select-active",
        family: "evm",
        address: connection.address,
        uid: connection.uid,
        stableId: connection.stableId,
        now: Date.now(),
      });
      if (!switchAccountAsync) return;
      const connector = wagmiConfig.connectors.find(
        (candidate) => candidate.uid === connection.uid,
      );
      if (!connector) {
        walletDebug("active-evm:switch-skipped", {
          uid: connection.uid,
          stableId: connection.stableId,
          reason: "connector-missing",
        });
        return;
      }
      try {
        await switchAccountAsync({ connector });
      } catch (error) {
        walletDebug("active-evm:cosmetic-switch-failed", {
          uid: connection.uid,
          stableId: connection.stableId,
          error: error instanceof Error ? error.message : String(error),
        });
      }
    },
    [registryStore, switchAccountAsync, wagmiConfig.connectors],
  );

  const connect = useCallback(
    async (id?: string) => {
      if (!id) {
        providerHooks.onConnectFallback?.(registryStore);
        return;
      }
      const connectorOptions = evmConnectors.map((candidate) => ({
        connector: candidate,
        option: toEvmWalletOption(candidate, installedWalletFlags),
      }));
      const normalizedId = canonicalWalletKey(id);
      let target =
        connectorOptions.find(
          ({ option, connector }) => option.id === id || connector.uid === id,
        )?.connector ??
        connectorOptions.find(({ connector }) => connector.id === id)
          ?.connector ??
        connectorOptions.find(({ option, connector }) => {
          if (canonicalWalletKey(option.label) !== normalizedId) return false;
          if (providerHooks.isProviderInternalConnector?.(connector)) {
            return false;
          }
          return true;
        })?.connector;
      if (target?.getProvider) {
        try {
          const provider = await target.getProvider();
          const actualKey = canonicalWalletKey(
            detectEvmProviderBrand(provider) ?? "",
          );
          if (actualKey && actualKey !== normalizedId) {
            const replacement = await findConnectorByProviderBrand(
              connectorOptions.map(({ connector }) => connector),
              normalizedId,
              target.uid,
            );
            if (replacement) {
              walletDebug("evm:connect-brand-mismatch", {
                requested: id,
                selected: target.id,
                actual: actualKey,
                replacement: replacement.id,
              });
              target = replacement;
            }
          }
        } catch (error) {
          walletDebug("evm:connect-brand-sniff-failed", {
            requested: id,
            connector: target.id,
            error: error instanceof Error ? error.message : String(error),
          });
        }
      }
      if (target && wagmiConnectAsync) {
        walletDebug("evm:connect-target", {
          requested: id,
          connector: target.name,
          uid: target.uid,
          stableId: target.id,
        });
        if (providerHooks.isProviderInternalConnector?.(target)) {
          providerHooks.onProviderReconnectRequested?.(registryStore);
        }
        const result = await wagmiConnectAsync({ connector: target });
        const connectedAddress = (
          result as { accounts?: readonly string[] } | undefined
        )?.accounts?.find((account) => account.startsWith("0x"));
        if (connectedAddress) {
          registryStore.dispatch({
            type: "user/connect-succeeded",
            family: "evm",
            address: connectedAddress,
            uid: target.uid,
            stableId: target.id,
            now: Date.now(),
          });
        }
        return;
      }
      providerHooks.onProviderReconnectRequested?.(registryStore);
      providerHooks.onConnectFallback?.(registryStore);
    },
    [
      evmConnectors,
      installedWalletFlags,
      providerHooks,
      registryStore,
      wagmiConnectAsync,
    ],
  );

  const disconnectAccount = useCallback(
    async (target: AomiAccount) => {
      const disconnectPlan = planEvmAccountDisconnect({
        target,
        connections: evmConnections,
      });
      walletDebug("evm:account-sign-out", {
        wallet: target.walletName ?? null,
        address: disconnectPlan.targetAddress,
        isProviderOwnedAccount: disconnectPlan.isProviderOwnedAccount,
        disconnecting: [...disconnectPlan.connectorIds],
        othersRemain: disconnectPlan.otherConnectionsRemain,
        sameAddressRemains: disconnectPlan.sameAddressConnectionsRemain,
      });
      registryStore.dispatch({
        type: "user/disconnect-account",
        address: disconnectPlan.targetAddress,
        uids: [...disconnectPlan.connectorIds],
        isProviderOwnedAccount: disconnectPlan.isProviderOwnedAccount,
        othersRemain: disconnectPlan.otherConnectionsRemain,
        markDroppedAddress: disconnectPlan.shouldMarkDroppedAddress,
        now: Date.now(),
      });
      providerHooks.onAccountDisconnectPlanned?.(disconnectPlan);
    },
    [evmConnections, providerHooks, registryStore],
  );

  const disconnect = useCallback(
    async (accountId?: string) => {
      if (accountId) {
        const target = selectAccounts(
          registryStore.getSnapshot(),
          "evm",
          Date.now(),
          selectedEvmChainId,
        ).find((account) => account.id === accountId);
        if (target) await disconnectAccount(target);
        return;
      }
      registryStore.dispatch({
        type: "user/disconnect-family",
        family: "evm",
        now: Date.now(),
      });
    },
    [disconnectAccount, registryStore, selectedEvmChainId],
  );

  const selectNetwork = useCallback(
    async (networkId: string | number) => {
      const chainId = Number(networkId);
      if (!Number.isFinite(chainId)) return;
      setSelectedEvmChainId(chainId);
      if (
        switchChainAsync &&
        activeConnector &&
        activeEvmConnection?.chainId !== chainId
      ) {
        evmSwitchInFlightRef.current = true;
        try {
          await switchChainAsync({
            chainId,
            connector: activeConnector,
          });
        } finally {
          evmSwitchInFlightRef.current = false;
        }
      }
    },
    [
      activeConnector,
      activeEvmConnection?.chainId,
      setSelectedEvmChainId,
      switchChainAsync,
    ],
  );

  const selectRuntimeAccounts = useCallback(
    (now: number) => selectAccounts(registryState, "evm", now, selectedEvmChainId),
    [registryState, selectedEvmChainId],
  );
  const selectRuntimeEvmIdentity = useCallback(
    (now: number) => selectEvmIdentity(registryState, now, selectedEvmChainId),
    [registryState, selectedEvmChainId],
  );

  const activeConnectorIsProviderInternal = activeConnector
    ? providerHooks.isProviderInternalConnector?.(activeConnector)
    : false;

  return {
    registryStore,
    registryState,
    status: "ready",
    activeEvmConnection,
    activeConnector,
    capabilities,
    chainsById,
    supportedChains,
    walletClient,
    getWalletClientFor,
    sendTransactionAsync,
    sendCallsSyncAsync,
    signTypedDataAsync,
    signMessageAsync,
    switchChainAsync,
    isSwitchingChain: isPending,
    activeAccount: selectRuntimeAccounts(Date.now()).find(
      (account) => account.active,
    ),
    options: evmWalletOptions,
    shouldUseExternalSigner: Boolean(
      activeConnector && !activeConnectorIsProviderInternal,
    ),
    identity: selectRuntimeEvmIdentity,
    accounts: selectRuntimeAccounts,
    selectAccount,
    connect,
    disconnect,
    selectNetwork,
  };
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import type { WalletRegistryStore } from "../../../registry/store";

type ParaAccountSnapshot = {
  isConnected: boolean;
  embedded: {
    isConnected?: boolean;
    wallets?: Array<{ address?: string; type?: string; isExternal?: boolean }>;
  };
  external: {
    evm?: {
      address?: string;
    };
  };
};

export function useParaSessionSource(
  store: WalletRegistryStore,
  opts: { paraAccount: ParaAccountSnapshot },
): void {
  const embeddedWallet =
    opts.paraAccount.embedded.wallets?.find(
      (wallet) => wallet.address && wallet.type?.toUpperCase() === "EVM",
    ) ?? opts.paraAccount.embedded.wallets?.find((wallet) => wallet.address);
  const embeddedEvmAddress =
    opts.paraAccount.external.evm?.address ?? embeddedWallet?.address ?? null;
  const isConnected = Boolean(
    opts.paraAccount.isConnected || opts.paraAccount.embedded.isConnected,
  );
  const snapshotKey = useMemo(
    () =>
      `${isConnected ? "up" : "down"}:${
        embeddedEvmAddress?.toLowerCase() ?? ""
      }`,
    [embeddedEvmAddress, isConnected],
  );
  const previousKeyRef = useRef<string | null>(null);

  useEffect(() => {
    if (previousKeyRef.current === snapshotKey) return;
    previousKeyRef.current = snapshotKey;
    store.dispatch({
      type: "provider/embedded-session-changed",
      up: isConnected,
      providerId: "para",
      uid: "para-session",
      stableId: "para",
      walletName: "Para",
      embeddedEvmAddress,
      now: Date.now(),
    });
  }, [embeddedEvmAddress, isConnected, snapshotKey, store]);
}

"use client";

import { useEffect, useMemo, useRef } from "react";
import type { WalletRegistryStore } from "../../registry/store";
import type { SafeSvmWalletState } from "./wallet-runtime";

export function useSvmRegistrySource(
  store: WalletRegistryStore,
  opts: { svmWallet: SafeSvmWalletState },
): void {
  const snapshotKey = useMemo(
    () =>
      `${opts.svmWallet.publicKey ?? ""}:${opts.svmWallet.walletName ?? ""}`,
    [opts.svmWallet.publicKey, opts.svmWallet.walletName],
  );
  const previousKeyRef = useRef<string | null>(null);

  useEffect(() => {
    if (previousKeyRef.current === snapshotKey) return;
    previousKeyRef.current = snapshotKey;
    store.dispatch({
      type: "svm/changed",
      publicKey: opts.svmWallet.publicKey ?? null,
      walletName: opts.svmWallet.walletName ?? null,
      now: Date.now(),
    });
  }, [opts.svmWallet.publicKey, opts.svmWallet.walletName, snapshotKey, store]);

}

"use client";

import type { AomiAccount } from "../../types";
import type { WagmiConnectionShape } from "./safe-hooks";

export type EvmAccountDisconnectPlan = {
  connectorIds: Set<string>;
  isProviderOwnedAccount: boolean;
  otherConnectionsRemain: boolean;
  sameAddressConnectionsRemain: boolean;
  shouldMarkDroppedAddress: boolean;
  targetAddress: string;
};

export function planEvmAccountDisconnect({
  target,
  connections,
}: {
  target: Pick<AomiAccount, "id" | "address" | "connectorIds" | "manageable">;
  connections: readonly WagmiConnectionShape[];
}): EvmAccountDisconnectPlan {
  const targetAddress = target.address.toLowerCase();
  const isProviderOwnedAccount = Boolean(target.manageable);
  const targetConnectorIds = new Set(
    isProviderOwnedAccount
      ? [target.id]
      : [target.id, ...(target.connectorIds ?? [])],
  );
  const connectorIds = new Set<string>();

  for (const connection of connections) {
    if (connection.address.toLowerCase() !== targetAddress) continue;
    if (!targetConnectorIds.has(connection.connectorId)) continue;
    connectorIds.add(connection.connectorId);
  }

  if (connectorIds.size === 0) {
    connectorIds.add(target.id);
  }

  const remainingConnections = connections.filter(
    (connection) => !connectorIds.has(connection.connectorId),
  );
  const sameAddressConnectionsRemain = remainingConnections.some(
    (connection) => connection.address.toLowerCase() === targetAddress,
  );

  return {
    connectorIds,
    isProviderOwnedAccount,
    otherConnectionsRemain: remainingConnections.length > 0,
    sameAddressConnectionsRemain,
    shouldMarkDroppedAddress: !sameAddressConnectionsRemain,
    targetAddress,
  };
}

import type { WalletSource } from "../types";

export type GracefulEvmIdentity = {
  address?: string;
  chainId?: number;
  connectorId?: string;
  walletName?: string;
  walletSource?: WalletSource;
};

export type GracefulEvmIdentityResult = {
  identity: GracefulEvmIdentity;
  disconnectedAt: number | null;
  usingCachedIdentity: boolean;
};

export function resolveGracefulEvmIdentity({
  current,
  previous,
  selectedChainId,
  disconnectedAt,
  now,
  graceMs,
  explicitDisconnect,
}: {
  current: GracefulEvmIdentity;
  previous: GracefulEvmIdentity | null;
  selectedChainId?: number;
  disconnectedAt: number | null;
  now: number;
  graceMs: number;
  explicitDisconnect: boolean;
}): GracefulEvmIdentityResult {
  if (current.address) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  if (!previous?.address || explicitDisconnect) {
    return {
      identity: current,
      disconnectedAt: null,
      usingCachedIdentity: false,
    };
  }

  const startedAt = disconnectedAt ?? now;
  if (now - startedAt > graceMs) {
    // Keep the original disconnect timestamp: resetting it to null here
    // would let the very next render restart the grace window (previous is
    // still cached), making the identity oscillate cached → empty → cached
    // for as long as the wallet stays disconnected. Only a live reconnect
    // (the `current.address` branch above) clears the timestamp.
    return {
      identity: current,
      disconnectedAt: startedAt,
      usingCachedIdentity: false,
    };
  }

  return {
    identity: {
      ...previous,
      chainId: selectedChainId ?? current.chainId ?? previous.chainId,
    },
    disconnectedAt: startedAt,
    usingCachedIdentity: true,
  };
}

"use client";

import { useMemo } from "react";
import { http, type Chain, type Transport } from "viem";

const FULL_TESTNET_ENABLED =
  process.env.NEXT_PUBLIC_USE_FULL_TESTNET === "true";
const FULL_TESTNET_RPC_MAP_RAW =
  process.env.NEXT_PUBLIC_FULL_TESTNET_RPC_MAP?.trim() ?? "";

export function parseRpcOverrides(raw: string): Record<number, string> {
  const trimmed = raw.trim();
  if (!trimmed) return {};

  const overrides: Record<number, string> = {};
  const writeOverride = (chainIdRaw: string, rpcUrlRaw: string) => {
    const chainId = Number(chainIdRaw.trim());
    const rpcUrl = rpcUrlRaw.trim();
    if (!Number.isInteger(chainId) || chainId <= 0 || !rpcUrl) return;

    try {
      overrides[chainId] = new URL(rpcUrl).toString();
    } catch {
      // Ignore malformed URLs so one bad env entry does not break the app.
    }
  };

  if (trimmed.startsWith("{")) {
    try {
      const parsed = JSON.parse(trimmed) as Record<string, unknown>;
      for (const [chainId, rpcUrl] of Object.entries(parsed ?? {})) {
        if (typeof rpcUrl === "string") {
          writeOverride(chainId, rpcUrl);
        }
      }
    } catch {
      return {};
    }
    return overrides;
  }

  for (const part of trimmed.split(",")) {
    const [chainId, ...rpcUrlParts] = part.split("=");
    if (!chainId || rpcUrlParts.length === 0) continue;
    writeOverride(chainId, rpcUrlParts.join("="));
  }

  return overrides;
}

const FULL_TESTNET_RPC_OVERRIDES = parseRpcOverrides(FULL_TESTNET_RPC_MAP_RAW);

export function isFullTestnet(): boolean {
  return (
    FULL_TESTNET_ENABLED && Object.keys(FULL_TESTNET_RPC_OVERRIDES).length > 0
  );
}

export function useFullTestnet<
  T extends readonly [Chain, ...Chain[]],
>(chains: T) {
  return useMemo(() => {
    const enabled = isFullTestnet();
    const routedChains = (enabled
      ? chains.map((chain) => {
          const rpcUrl = FULL_TESTNET_RPC_OVERRIDES[chain.id];
          if (!rpcUrl) return chain;

          return {
            ...chain,
            rpcUrls: {
              ...chain.rpcUrls,
              default: {
                ...chain.rpcUrls.default,
                http: [rpcUrl],
              },
              public: chain.rpcUrls.public
                ? {
                    ...chain.rpcUrls.public,
                    http: [rpcUrl],
                  }
                : {
                    http: [rpcUrl],
                  },
            },
          };
        })
      : chains) as unknown as T;

    return {
      enabled,
      routedChains,
      routedChainIds: new Set(
        Object.keys(FULL_TESTNET_RPC_OVERRIDES).map(Number),
      ) as ReadonlySet<number>,
      transports: Object.fromEntries(
        routedChains.map((chain) => [
          chain.id,
          http(chain.rpcUrls.default.http[0]),
        ]),
      ) as Record<number, Transport>,
    };
  }, [chains]);
}

"use client";

import { useEffect, useMemo, useRef, type ReactNode } from "react";
import type { Chain } from "viem";
import { useAccount, useSwitchChain } from "wagmi";

export {
  isFullTestnet,
  parseRpcOverrides,
  useFullTestnet,
} from "./full-testnet-config";

type FullTestnetWalletRouterProps = {
  enabled: boolean;
  chains: readonly Chain[];
  routedChainIds: ReadonlySet<number>;
  logLabel?: string;
  children?: ReactNode;
};

export function FullTestnetWalletRouter({
  enabled,
  chains,
  routedChainIds,
  logLabel = "FullTestnetWalletRouter",
  children,
}: FullTestnetWalletRouterProps) {
  const { isConnected, chainId, connector } = useAccount();
  const { switchChainAsync } = useSwitchChain();
  const attemptedChainIdsRef = useRef(new Set<number>());
  const chainsById = useMemo(
    () => Object.fromEntries(chains.map((chain) => [chain.id, chain])),
    [chains],
  ) as Record<number, Chain>;

  useEffect(() => {
    if (!enabled || !isConnected || !chainId || !routedChainIds.has(chainId)) {
      return;
    }
    if (attemptedChainIdsRef.current.has(chainId)) {
      return;
    }

    attemptedChainIdsRef.current.add(chainId);

    const ensureWalletOnChain = async () => {
      const chain = chainsById[chainId];
      if (!chain) return;

      try {
        const provider = await connector?.getProvider();
        if (provider && typeof provider === "object" && "request" in provider) {
          try {
            await (
              provider as {
                request: (args: {
                  method: string;
                  params?: unknown[];
                }) => Promise<unknown>;
              }
            ).request({
              method: "wallet_addEthereumChain",
              params: [
                {
                  chainId: `0x${chain.id.toString(16)}`,
                  chainName: chain.name,
                  nativeCurrency: chain.nativeCurrency,
                  rpcUrls: chain.rpcUrls.default.http,
                  blockExplorerUrls: chain.blockExplorers?.default?.url
                    ? [chain.blockExplorers.default.url]
                    : undefined,
                },
              ],
            });
          } catch (error) {
            console.info(`[${logLabel}] wallet_addEthereumChain result`, error);
          }
        }

        if (switchChainAsync) {
          await switchChainAsync({ chainId });
        }
      } catch (error) {
        console.error(
          `[${logLabel}] Failed to route wallet for chain ${chainId}`,
          error,
        );
      }
    };

    void ensureWalletOnChain();
  }, [
    chainId,
    chainsById,
    connector,
    enabled,
    isConnected,
    logLabel,
    routedChainIds,
    switchChainAsync,
  ]);

  return <>{children}</>;
}

"use client";

import {
  createContext,
  useContext,
  useEffect,
  useMemo,
  useState,
  type ReactNode,
} from "react";
import type { Chain } from "viem";
import type { AomiNetworkTarget, SvmNetworkOption } from "./types";
import { resolveSelectedSvmNetwork } from "./catalog/svm-networks";

type WalletNetworkPreferences = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
};

const STORAGE_PREFIX = "aomi.wallet-preferences";

function storageKey(key: string): string {
  return `${STORAGE_PREFIX}.${key}`;
}

function loadWalletNetworkPreferences(key: string): WalletNetworkPreferences {
  try {
    const raw = globalThis.localStorage?.getItem(storageKey(key));
    if (!raw) return {};
    const parsed: unknown = JSON.parse(raw);
    if (typeof parsed !== "object" || parsed === null) return {};
    const stored = parsed as WalletNetworkPreferences;
    return {
      selectedEvmChainId:
        typeof stored.selectedEvmChainId === "number"
          ? stored.selectedEvmChainId
          : undefined,
      selectedSolanaNetworkId:
        typeof stored.selectedSolanaNetworkId === "string"
          ? stored.selectedSolanaNetworkId
          : undefined,
    };
  } catch {
    return {};
  }
}

function saveWalletNetworkPreferences(
  key: string,
  prefs: WalletNetworkPreferences,
): void {
  try {
    globalThis.localStorage?.setItem(storageKey(key), JSON.stringify(prefs));
  } catch {
    // localStorage unavailable or over quota — preferences are best-effort.
  }
}

type NetworkPreferencesContextValue = {
  selectedEvmChainId?: number;
  selectedSolanaNetworkId?: string;
  supportedEvmChains: readonly Chain[];
  supportedSolanaNetworks: readonly SvmNetworkOption[];
  selectedSolanaNetwork?: SvmNetworkOption;
  setSelectedEvmChainId: (chainId: number | undefined) => void;
  setSelectedSolanaNetworkId: (networkId: string | undefined) => void;
  selectTarget: (target: AomiNetworkTarget) => void;
};

const NetworkPreferencesContext =
  createContext<NetworkPreferencesContextValue | null>(null);

export function AomiWalletNetworkPreferencesProvider({
  children,
  evmChains,
  solanaNetworks,
  storageKey = "default",
}: {
  children: ReactNode;
  evmChains: readonly Chain[];
  solanaNetworks: readonly SvmNetworkOption[];
  storageKey?: string;
}) {
  const [persisted] = useState(() => loadWalletNetworkPreferences(storageKey));

  const [selectedEvmChainId, setSelectedEvmChainId] = useState<
    number | undefined
  >(() =>
    persisted.selectedEvmChainId !== undefined &&
    evmChains.some((chain) => chain.id === persisted.selectedEvmChainId)
      ? persisted.selectedEvmChainId
      : evmChains[0]?.id,
  );
  const [selectedSolanaNetworkId, setSelectedSolanaNetworkId] = useState<
    string | undefined
  >(() =>
    persisted.selectedSolanaNetworkId &&
    solanaNetworks.some((n) => n.id === persisted.selectedSolanaNetworkId)
      ? persisted.selectedSolanaNetworkId
      : resolveSelectedSvmNetwork(solanaNetworks)?.id,
  );

  useEffect(() => {
    if (!evmChains.length) {
      setSelectedEvmChainId(undefined);
      return;
    }
    setSelectedEvmChainId((current) =>
      evmChains.some((chain) => chain.id === current)
        ? current
        : evmChains[0]?.id,
    );
  }, [evmChains]);

  useEffect(() => {
    if (!solanaNetworks.length) {
      setSelectedSolanaNetworkId(undefined);
      return;
    }
    setSelectedSolanaNetworkId((current) =>
      solanaNetworks.some((network) => network.id === current)
        ? current
        : resolveSelectedSvmNetwork(solanaNetworks)?.id,
    );
  }, [evmChains.length, solanaNetworks]);

  useEffect(() => {
    saveWalletNetworkPreferences(storageKey, {
      selectedEvmChainId,
      selectedSolanaNetworkId,
    });
  }, [storageKey, selectedEvmChainId, selectedSolanaNetworkId]);

  const selectedSolanaNetwork = useMemo(
    () =>
      solanaNetworks.length
        ? resolveSelectedSvmNetwork(solanaNetworks, selectedSolanaNetworkId)
        : undefined,
    [selectedSolanaNetworkId, solanaNetworks],
  );

  const value = useMemo<NetworkPreferencesContextValue>(
    () => ({
      selectedEvmChainId,
      selectedSolanaNetworkId,
      supportedEvmChains: evmChains,
      supportedSolanaNetworks: solanaNetworks,
      selectedSolanaNetwork,
      setSelectedEvmChainId,
      setSelectedSolanaNetworkId,
      selectTarget: (target: AomiNetworkTarget) => {
        if (target.family === "evm") {
          setSelectedEvmChainId(target.chainId);
          return;
        }
        setSelectedSolanaNetworkId(target.networkId);
      },
    }),
    [
      evmChains,
      selectedEvmChainId,
      selectedSolanaNetwork,
      selectedSolanaNetworkId,
      solanaNetworks,
    ],
  );

  return (
    <NetworkPreferencesContext.Provider value={value}>
      {children}
    </NetworkPreferencesContext.Provider>
  );
}

export function useAomiWalletNetworkPreferences(): NetworkPreferencesContextValue {
  const context = useContext(NetworkPreferencesContext);
  if (!context) {
    throw new Error(
      "useAomiWalletNetworkPreferences must be used within AomiWalletNetworkPreferencesProvider",
    );
  }
  return context;
}

/**
 * Non-throwing variant for components that may render without a wallet
 * provider in the tree — e.g. a standalone <AomiFrame /> on a docs page or
 * during SSR/prerender, where no wallet kit provider mounts the network
 * preferences context. Returns null when the provider is absent so callers
 * can degrade gracefully instead of crashing the render.
 */
export function useOptionalAomiWalletNetworkPreferences(): NetworkPreferencesContextValue | null {
  return useContext(NetworkPreferencesContext);
}

