/**
 * Identify which wallet brand actually answers behind an injected provider.
 *
 * Connector names lie: with Rabby (or Phantom, Brave, …) set as the default
 * wallet, the "MetaMask" connector binds to Rabby's provider — Rabby sets
 * `isMetaMask` for compatibility. So specific-brand flags are checked before
 * the generic `isMetaMask`.
 */
export function detectEvmProviderBrand(provider: unknown): string | undefined {
  if (!provider || typeof provider !== "object") return undefined;
  if (readInjectedFlag(provider, "isRabby")) return "Rabby";
  if (readInjectedFlag(provider, "isPhantom")) return "Phantom";
  if (readInjectedFlag(provider, "isBraveWallet")) return "Brave Wallet";
  if (readInjectedFlag(provider, "isRainbow")) return "Rainbow";
  if (readInjectedFlag(provider, "isCoinbaseWallet")) {
    return "Coinbase Wallet";
  }
  if (readInjectedFlag(provider, "isMetaMask")) return "MetaMask";
  return undefined;
}

export type EvmConnectionBrandInput = {
  connectorId: string;
  address: string;
};

/**
 * Resolve the real brand for each live EVM connection by sniffing the
 * underlying provider. Returns `connectorId → brand label`; connections whose
 * provider exposes no brand flags (embedded SDK wallets, WalletConnect, ...) are
 * absent — callers fall back to the connector name.
 *
 * Re-sniffs whenever the connection set changes, so flipping the wallet's
 * "default wallet" setting is picked up without a page refresh.
 */
export function useEvmProviderBrands(
  connections: readonly EvmConnectionBrandInput[],
  connectors: readonly Connector[],
): Record<string, string> {
  const [brands, setBrands] = useState<Record<string, string>>({});
  // Re-sniff on membership changes without retriggering on unrelated renders.
  const membershipKey = useMemo(
    () =>
      connections
        .map((connection) => `${connection.connectorId}:${connection.address}`)
        .sort()
        .join("|"),
    [connections],
  );
  const connectionsRef = useRef(connections);
  connectionsRef.current = connections;
  const connectorsRef = useRef(connectors);
  connectorsRef.current = connectors;

  useEffect(() => {
    if (!membershipKey) {
      setBrands((previous) => (Object.keys(previous).length ? {} : previous));
      return;
    }

    let cancelled = false;
    void Promise.all(
      connectionsRef.current.map(async (connection) => {
        const connector = connectorsRef.current.find(
          (candidate) => candidate.uid === connection.connectorId,
        );
        if (!connector?.getProvider) return null;
        try {
          const provider = await connector.getProvider();
          const brand = detectEvmProviderBrand(provider);
          return brand ? ([connection.connectorId, brand] as const) : null;
        } catch {
          return null;
        }
      }),
    ).then((entries) => {
      if (cancelled) return;
      setBrands(
        Object.fromEntries(
          entries.filter(
            (entry): entry is readonly [string, string] => entry !== null,
          ),
        ),
      );
    });

    return () => {
      cancelled = true;
    };
  }, [membershipKey]);

  return brands;
}

"use client";

import type { Chain, Transport } from "viem";
import { http } from "viem";
import { createConfig, type Config, type CreateConnectorFn } from "wagmi";
import {
  baseAccount,
  coinbaseWallet,
  injected,
  walletConnect,
} from "wagmi/connectors";
import type { EvmWalletId, EvmWalletPreset } from "./wallet-ids";
import { EVM_PRESETS } from "./wallet-ids";

export const AOMI_DEFAULT_WC_PROJECT_ID =
  process.env.NEXT_PUBLIC_AOMI_WC_PROJECT_ID ??
  process.env.NEXT_PUBLIC_WALLETCONNECT_PROJECT_ID ??
  process.env.NEXT_PUBLIC_PROJECT_ID;

export type ResolvedEvmWalletsConfig = {
  chains: readonly [Chain, ...Chain[]];
  preset?: EvmWalletPreset;
  wallets?: readonly EvmWalletId[];
  connectors?: readonly CreateConnectorFn[];
  walletConnectProjectId?: string;
  coinbase?: boolean;
  appName?: string;
  appLogoUrl?: string | null;
  transports?: Record<number, Transport>;
  ssr?: boolean;
  includeBaseAccount?: boolean;
};

function defaultHttpTransports(
  chains: readonly Chain[],
): Record<number, Transport> {
  return Object.fromEntries(
    chains.map((chain) => [chain.id, http(chain.rpcUrls.default.http[0])]),
  );
}

function connectorLooksLikeWalletConnect(
  connector: CreateConnectorFn,
): boolean {
  const meta = connector as unknown as {
    id?: string;
    name?: string;
    type?: string;
  };
  const text = [meta.id, meta.name, meta.type].filter(Boolean).join(" ");
  return /wallet\s*connect|walletconnect/i.test(text);
}

function warnDuplicateWalletConnect(): void {
  if (process.env.NODE_ENV === "production") return;
  console.warn(
    "[aomi-wallet-kit] wallets.evm.connectors included a WalletConnect-like connector. Aomi owns the WalletConnect connector; pass walletConnectProjectId instead.",
  );
}

export function createAomiEvmConfig(input: ResolvedEvmWalletsConfig): Config {
  const wanted = new Set(
    input.wallets ?? EVM_PRESETS[input.preset ?? "popular"],
  );
  const wcProjectId =
    input.walletConnectProjectId ?? AOMI_DEFAULT_WC_PROJECT_ID;
  const hostConnectors = (input.connectors ?? []).filter((connector) => {
    if (!connectorLooksLikeWalletConnect(connector)) return true;
    warnDuplicateWalletConnect();
    return false;
  });

  const connectors: CreateConnectorFn[] = [
    injected({ shimDisconnect: true }),
    ...(wanted.has("walletconnect") && wcProjectId
      ? [walletConnect({ projectId: wcProjectId, showQrModal: true })]
      : []),
    ...(input.coinbase !== false && wanted.has("coinbase")
      ? [
          coinbaseWallet({
            appName: input.appName ?? "Aomi",
            appLogoUrl: input.appLogoUrl ?? undefined,
          }),
        ]
      : []),
    ...(wanted.has("baseAccount") || input.includeBaseAccount
      ? [
          baseAccount({
            appName: input.appName ?? "Aomi",
            appLogoUrl: input.appLogoUrl ?? null,
            paymasterUrls: {},
          }),
        ]
      : []),
    ...hostConnectors,
  ];

  return createConfig({
    chains: input.chains,
    connectors,
    transports: input.transports ?? defaultHttpTransports(input.chains),
    multiInjectedProviderDiscovery: true,
    ssr: input.ssr ?? true,
  });
}

